installer-gui-script.script:
function shieldCheck() {
  if (system.compareVersions(system.version.ProductVersion, '13.0') < 0) {
    my.result.title = 'macOS 13 ou plus récent requis (macOS 13 or later required)';
    my.result.message = 'RAGbase Shield demande macOS 13 (Ventura) ou une version plus récente. ' +
                        'RAGbase Shield needs macOS 13 (Ventura) or later.';
    my.result.type = 'Fatal';
    return false;
  }
  return true;
}
